package com.shopsphere.dao;
import com.shopsphere.model.Product; import com.shopsphere.util.DB; import java.sql.*; import java.util.*; import java.math.BigDecimal;
public class ProductDAO {
 private Product map(ResultSet r)throws SQLException{return new Product(r.getLong("product_id"),r.getString("name"),r.getString("brand"),r.getString("description"),r.getBigDecimal("price"),r.getBigDecimal("discount"),r.getInt("stock"),r.getString("image_url"));}
 public List<Product> findAll(String search)throws SQLException {List<Product> out=new ArrayList<>();String q="SELECT * FROM products WHERE status=TRUE AND (?='' OR name LIKE ? OR brand LIKE ? OR description LIKE ?) ORDER BY product_id DESC";try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement(q)){String s=search==null?"":search.trim();p.setString(1,s);p.setString(2,"%"+s+"%");p.setString(3,"%"+s+"%");p.setString(4,"%"+s+"%");try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}return out;}
 public Product find(long id)throws SQLException {try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM products WHERE product_id=? AND status=TRUE")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 public List<Product> findCart(long userId)throws SQLException {List<Product> out=new ArrayList<>();String q="SELECT p.*, c.quantity AS cart_quantity FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=? AND p.status=TRUE";try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,userId);try(ResultSet r=p.executeQuery()){while(r.next()){Product x=map(r);for(int i=0;i<r.getInt("cart_quantity");i++)out.add(x);}}}return out;}
 public void add(long id,String name,String brand,String description,BigDecimal price,int stock,String image)throws SQLException {String q="INSERT INTO products(name,brand,description,price,stock,image_url,status) VALUES(?,?,?,?,?,?,TRUE)";try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,name);p.setString(2,brand);p.setString(3,description);p.setBigDecimal(4,price);p.setInt(5,stock);p.setString(6,image);p.executeUpdate();}}
 public void setStatus(long id,boolean status)throws SQLException {try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("UPDATE products SET status=? WHERE product_id=?")){p.setBoolean(1,status);p.setLong(2,id);p.executeUpdate();}}
}
